-- Score events sent by the umpire tablet: each point and each undo, timestamped.
-- The id is generated by the tablet, so that an event sent twice is recognized.
-- The score of each match, counted from its events, is kept on the match.

CREATE TABLE score_event (
    id          UUID        PRIMARY KEY,
    match_id    UUID        NOT NULL REFERENCES match (id) ON DELETE CASCADE,
    sequence    INTEGER     NOT NULL,
    type        VARCHAR(10) NOT NULL,
    side        VARCHAR(1),
    occurred_at TIMESTAMPTZ NOT NULL,
    received_at TIMESTAMPTZ NOT NULL,
    tablet_id   UUID        REFERENCES tablet (id) ON DELETE SET NULL,
    CONSTRAINT score_event_sequence_check CHECK (sequence > 0),
    CONSTRAINT score_event_type_check CHECK (type IN ('POINT', 'UNDO')),
    -- A point has the side that won the rally, an undo has none
    CONSTRAINT score_event_side_check CHECK ((type = 'POINT') = (side IN ('A', 'B'))
        AND (type = 'POINT') = (side IS NOT NULL)),
    CONSTRAINT score_event_match_sequence_key UNIQUE (match_id, sequence)
);

ALTER TABLE match
    ADD COLUMN games_a      INTEGER[]  NOT NULL DEFAULT '{}',
    ADD COLUMN games_b      INTEGER[]  NOT NULL DEFAULT '{}',
    ADD COLUMN score_winner VARCHAR(1),
    ADD CONSTRAINT match_games_check CHECK (cardinality(games_a) = cardinality(games_b)),
    ADD CONSTRAINT match_score_winner_check CHECK (score_winner IN ('A', 'B'));
